import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"彼得·伦德","description":"","frontmatter":{"title":"彼得·伦德","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/彼得·伦德.md","filePath":"04_people/彼得·伦德.md"}'),o={name:"04_people/彼得·伦德.md"};function n(i,e,s,_,h,d){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="彼得·伦德-peter-lund" tabindex="-1">彼得·伦德（Peter Lund） <a class="header-anchor" href="#彼得·伦德-peter-lund" aria-label="Permalink to &quot;彼得·伦德（Peter Lund）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：德克斯特鞋业高管</li><li><strong>与巴菲特关系</strong>：伯克希尔旗下制鞋公司的高管</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>彼得·伦德是德克斯特鞋业（Dexter Shoe Company）的高级管理人员。德克斯特鞋业由哈罗德·阿尔方德创立，在美国制鞋行业有着深厚的积累和良好的市场声誉。公司专注于男女鞋及童鞋的生产与销售，拥有覆盖全美的零售网络和成熟的供应链体系，在竞争激烈的美国鞋类市场中保持着稳定的地位。</p><p>在被伯克希尔·哈撒韦收购后，德克斯特鞋业继续由原有管理团队独立运营。伦德作为公司管理层的核心成员，在德克斯特鞋业的日常管理中承担重要职责，与创始人阿尔方德及其他高管共同负责公司的战略决策和运营管理。在伯克希尔的控股框架下，管理层的稳定性和专业能力对于业务的平稳过渡至关重要。</p><p>伦德在确保德克斯特鞋业在被收购后保持业务连续性方面发挥了积极作用。他与其他高管协作，推动公司在产品研发、市场营销和渠道拓展等方面的持续改进，使德克斯特品牌在新的所有权结构下仍能保持市场竞争力。德克斯特鞋业作为伯克希尔制鞋板块的一员，在伦德和管理团队的努力下继续为伯克希尔的整体业绩做出贡献。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>收购前</strong>：担任德克斯特鞋业高管，参与公司日常管理</li><li><strong>收购过渡期</strong>：在公司被伯克希尔收购期间协助维持业务稳定</li><li><strong>收购后</strong>：继续担任高管，推动德克斯特在伯克希尔体系下的持续发展</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=彼得·伦德在1993年股东信中的原话">1993年：完整翻译|/01_letters/1993年/翻译</a></li><li><a href="/search.html?q=彼得·伦德在1999年股东信中的原话">1999年：完整翻译|/01_letters/1999年/翻译</a></li></ul>',11)])])}const u=a(o,[["render",n]]);export{c as __pageData,u as default};
